handleMouse(event: Parameters<CustomEditor["handleMouse"]>[0]): ReturnType<CustomEditor["handleMouse"]> {
	const layout = this.floatMouseLayout;
	if (!layout) return super.handleMouse(event);
	// pi row model: padding=0, content=1…N, hint=N+1. A loon band fills it exactly - row 0
	// is its label slot, which pi ignores - so loon's rows are already native and nothing
	// is subtracted. Float still opens with a padding row of its own, so its rows sit one
	// lower and lose that one here. Only float translates; neon/fallback is untouched.
	const shift = layout.chrome === "loon" ? 0 : 1;
